'use strict';

var resolve = require( 'path' ).resolve;
var bench = require( '@stdlib/bench' );
var Float64Array = require( '@stdlib/array/float64' );
var format = require( '@stdlib/string/format' );
var tryRequire = require( '@stdlib/utils/try-require' );
var pkg = require( './../package.json' ).name;
var routine = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': routine instanceof Error
};

/**
* Creates a diagonal positive-definite matrix benchmark.
*
* @private
* @param {integer} N - matrix order
* @param {string} uplo - stored triangle
* @returns {Function} benchmark function
*/
function createBenchmark( N, uplo ) {
	var WORK = new Float64Array( 2*N );
	var AF = new Float64Array( N*N );
	var A = new Float64Array( N*N );
	var i;

	for ( i = 0; i < N; i++ ) {
		A[i*(N+1)] = 0.25;
		AF[i*(N+1)] = 0.5;
	}
	return benchmark;

	/**
	* Measures reciprocal pivot growth.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var value;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			value = routine( 'row-major', uplo, N, A, N, AF, N, WORK );
			if ( value !== 0.5 ) {
				b.fail( 'unexpected growth factor' );
			}
		}
		b.toc();
		b.pass( 'benchmark finished' );
		b.end();
	}
}

bench( format( '%s:N=4,uplo=upper', pkg ), opts, createBenchmark( 4, 'upper' ) );
bench( format( '%s:N=4,uplo=lower', pkg ), opts, createBenchmark( 4, 'lower' ) );
bench( format( '%s:N=32,uplo=upper', pkg ), opts, createBenchmark( 32, 'upper' ) );
bench( format( '%s:N=32,uplo=lower', pkg ), opts, createBenchmark( 32, 'lower' ) );
